    concept1Desc: "Residual paths provide a direct route for information and gradients around sublayers and can make deep networks easier to optimize. They reduce optimization difficulties but do not alone guarantee stable training.",
    concept2Title: 'Layer Normalization',
    concept2Desc: "LayerNorm normalizes across a token’s feature dimension. The original Transformer uses Post-Norm; many decoder architectures use Pre-Norm or RMSNorm. The order changes the residual path.",
    concept3Title: 'Positional Encoding',
    concept3Desc: 'Since attention has no inherent notion of order, position must be explicitly injected. The original paper used fixed sinusoidal functions; modern models typically use learned position embeddings or relative position encodings like RoPE.',

