    reverseProcessDesc: 'Generation starts from noise and applies learned denoising steps. The model predicts a cleaner state (or the noise residual) and iteratively moves toward a realistic sample.',
    noisePredictionIntuition: 'Noise Prediction Intuition',
    noisePredictionIntuitionDesc: 'Predicting noise is often easier than directly predicting the clean sample. Once noise is estimated, you can subtract it and recover structure progressively.',
    schedulers: 'Schedulers: Linear vs Cosine',
    schedulersDesc: 'Schedulers define how much noise is added or removed per step. They strongly affect stability, sample quality, and speed.',
