    schedulerLinearDesc: 'Noise changes at a constant rate per step. Simple, predictable, and easy to implement.',
    schedulerCosineTitle: 'Cosine schedule',
    schedulerCosineDesc: 'Allocates denoising effort non-linearly, often preserving useful signal longer and improving perceptual quality.',
    scoreMatching: 'Score Matching Intuition',
    scoreMatchingDesc: 'A score function estimates the gradient of log-density, pointing toward more likely data regions. Denoising updates follow this direction, nudging noisy states back to the data manifold.',
