    whatIs: 'What is Programmatic Tool Calling?',
    whatIsDesc: 'Programmatic tool calling lets an AI agent write code that invokes tools inside a sandboxed execution environment — instead of requiring a separate model round-trip for every tool call. The agent writes a script, the runtime executes it, and tool calls happen directly from the code. Only the final result is returned to the model\'s context window.',
