    hardwareStoryDesc: 'Modern AI is mostly enormous linear algebra under brutal constraints: power, memory bandwidth, latency, interconnect, and cost. GPUs won because they are programmable and massively parallel. Custom chips exist because hyperscalers can save huge money when a workload is predictable enough to harden into silicon.',
    tradeoffNote: 'The key trade-off is specialization versus flexibility. A custom ASIC can be far more efficient than a general GPU, but only if the models, operators, compiler, and deployment scale justify the loss of flexibility.',
    zooTitle: 'The accelerator zoo',
    examplesLabel: 'Examples:',
    limitsTitle: 'What actually limits performance?',
    strategicTitle: 'The strategic reason companies build their own chips',
    strategicDesc1: 'Custom silicon is not just about peak speed. It is about supply, margin, roadmap control, and avoiding total dependence on one vendor. Google TPUs, AWS Trainium and Inferentia, Microsoft Maia, and Meta MTIA all reflect the same pressure: AI demand is so large that hardware becomes product strategy.',
    strategicDesc2: 'But the risk is real: if the software stack is weak or model architecture shifts, a specialized chip can become an expensive dead end. The winning platform is usually chip plus compiler plus kernels plus networking plus developer experience.',
